<?php

declare(strict_types=1);

use HardnessWebhooks\Delivery\DeliveryRepository;
use HardnessWebhooks\Delivery\DestinationValidationException;
use HardnessWebhooks\Delivery\DestinationValidator;
use HardnessWebhooks\Delivery\HttpClientInterface;
use HardnessWebhooks\Delivery\HttpResult;
use HardnessWebhooks\Delivery\ValidatedDestination;
use HardnessWebhooks\Delivery\WebhookHttpDispatcher;
use HardnessWebhooks\Secrets\SecretVersionService;
use HardnessWebhooks\Security\HmacVerifier;
use HardnessWebhooks\Security\SecretCipher;

require_once dirname(__DIR__) . '/autoload.php';

function task08Assert(bool $condition, string $message): void { if (!$condition) { throw new RuntimeException('Assertion failed: ' . $message); } }
function task08Exec(mysqli $connection, string $sql, string $types = '', array $values = array()): mysqli_stmt { $statement = $connection->prepare($sql); if ($statement === false) { throw new RuntimeException('Database prepare failed.'); } if ($types !== '') { $params = array($types); foreach ($values as $key => $value) { $params[] = &$values[$key]; } call_user_func_array(array($statement, 'bind_param'), $params); } if (!$statement->execute()) { $statement->close(); throw new RuntimeException('Database execution failed.'); } return $statement; }
function task08One(mysqli $connection, string $sql, string $types, array $values): array { $statement = task08Exec($connection, $sql, $types, $values); $row = $statement->get_result()->fetch_assoc(); $statement->close(); return is_array($row) ? $row : array(); }
function task08Cleanup(mysqli $connection, int $companyId): void { task08Exec($connection, 'DELETE a FROM WHK005 a INNER JOIN WHK004 d ON d.WHK004_Id = a.WHK005_WHK004_Id INNER JOIN WHK003 e ON e.WHK003_Id = d.WHK004_WHK003_Id WHERE e.WHK003_C004_Id = ?', 'i', array($companyId))->close(); task08Exec($connection, 'DELETE d FROM WHK004 d INNER JOIN WHK003 e ON e.WHK003_Id = d.WHK004_WHK003_Id WHERE e.WHK003_C004_Id = ?', 'i', array($companyId))->close(); task08Exec($connection, 'DELETE FROM WHK003 WHERE WHK003_C004_Id = ?', 'i', array($companyId))->close(); task08Exec($connection, 'DELETE FROM WHK002 WHERE WHK002_C004_Id = ?', 'i', array($companyId))->close(); task08Exec($connection, 'DELETE v FROM WHK007 v INNER JOIN WHK001 e ON e.WHK001_Id = v.WHK007_WHK001_Id WHERE e.WHK001_C004_Id = ?', 'i', array($companyId))->close(); task08Exec($connection, 'DELETE FROM WHK001 WHERE WHK001_C004_Id = ?', 'i', array($companyId))->close(); }
function task08Delivery(mysqli $connection, int $companyId, int $endpointId, int $subscriptionId, int $secretId, string $url, string $payload): int { $eventId = 'task08-' . bin2hex(random_bytes(12)); task08Exec($connection, "INSERT INTO WHK003 (WHK003_Event_Id, WHK003_C004_Id, WHK003_Type, WHK003_Schema_Version, WHK003_Aggregate_Type, WHK003_Aggregate_Id, WHK003_Payload, WHK003_Occurred_At) VALUES (?, ?, 'financial_analysis.requested', '1', 'order', ?, ?, UTC_TIMESTAMP())", 'siss', array($eventId, $companyId, $eventId, $payload))->close(); $eventRecordId = (int) $connection->insert_id; $deliveryId = '00000000-0000-4000-8000-' . substr(bin2hex(random_bytes(8)), 0, 12); task08Exec($connection, "INSERT INTO WHK004 (WHK004_Delivery_Id, WHK004_C004_Id, WHK004_WHK003_Id, WHK004_WHK001_Id, WHK004_WHK002_Id, WHK004_WHK007_Id, WHK004_Destination_URL, WHK004_Status, WHK004_Next_Attempt_At) VALUES (?, ?, ?, ?, ?, ?, ?, 'P', UTC_TIMESTAMP())", 'siiiiis', array($deliveryId, $companyId, $eventRecordId, $endpointId, $subscriptionId, $secretId, $url))->close(); return (int) $connection->insert_id; }

final class Task08Validator extends DestinationValidator { /** @var array<int,string> */ private $addresses; /** @param array<int,string> $addresses */ public function __construct(array $addresses) { $this->addresses = $addresses; } /** @return array<int,string> */ protected function resolve(string $host): array { return $this->addresses; } }
final class Task08Client implements HttpClientInterface { /** @var HttpResult */ private $result; /** @var string */ public $body = ''; /** @var array<string,string> */ public $headers = array(); public function __construct(HttpResult $result) { $this->result = $result; } public function post(ValidatedDestination $destination, string $rawBody, array $headers): HttpResult { $this->body = $rawBody; $this->headers = $headers; return $this->result; } }

$configPath = (string) (getenv('WEBHOOKS_TEST_ERP_CONFIG') ?: '');
if ($configPath === '' || !is_file($configPath)) { fwrite(STDERR, "WEBHOOKS_TEST_ERP_CONFIG must identify the explicit DEV ERP configuration.\n"); exit(2); }
$confUsuario = array(); require $configPath; $connection = new mysqli((string) $confUsuario['dbHost'], (string) $confUsuario['dbUser'], (string) $confUsuario['dbPass'], (string) $confUsuario['dbDatabase']);
if ($connection->connect_errno !== 0) { throw new RuntimeException('Could not connect to explicit DEV database.'); } $connection->set_charset('utf8mb4');
$companyId = 987654325; $cipher = new SecretCipher(random_bytes(32)); $secrets = new SecretVersionService($cipher); $repository = new DeliveryRepository(90);
try {
    task08Cleanup($connection, $companyId);
    $url = 'https://public.example.test/hook'; task08Exec($connection, "INSERT INTO WHK001 (WHK001_C004_Id, WHK001_Nome, WHK001_URL, WHK001_URL_Hash, WHK001_Status) VALUES (?, 'Task 08 synthetic', ?, ?, 'A')", 'iss', array($companyId, $url, hash('sha256', $url, true)))->close(); $endpointId = (int) $connection->insert_id;
    $version = $secrets->createVersion($connection, $endpointId); task08Exec($connection, "INSERT INTO WHK002 (WHK002_C004_Id, WHK002_WHK001_Id, WHK002_Event_Type, WHK002_Status) VALUES (?, ?, 'financial_analysis.requested', 'A')", 'ii', array($companyId, $endpointId))->close(); $subscriptionId = (int) $connection->insert_id;

    $validator = new DestinationValidator();
    foreach (array('http://example.com/hook', 'https://user:pass@example.com/hook', 'https://example.com:444/hook', 'https://127.0.0.1/hook', 'https://[::1]/hook') as $invalid) { try { $validator->validate($invalid); task08Assert(false, 'insecure URL must be rejected'); } catch (DestinationValidationException $exception) { } }
    foreach (array('127.0.0.1', '10.0.0.1', '169.254.169.254', '192.168.1.1', '224.0.0.1', '::1', 'fc00::1', 'fe80::1') as $address) { task08Assert(!DestinationValidator::isPublicAddress($address), 'reserved IPv4/IPv6 is rejected'); }
    task08Assert(DestinationValidator::isPublicAddress('93.184.216.34') && DestinationValidator::isPublicAddress('2606:2800:220:1:248:1893:25c8:1946'), 'public IPv4/IPv6 is accepted');

    $payload = '{"z":"raw\\/bytes","n":1}'; $deliveryId = task08Delivery($connection, $companyId, $endpointId, $subscriptionId, $version->getId(), $url, $payload); task08Assert($repository->tryClaim($connection, $deliveryId, 'task08-ok'), 'success delivery claimed'); $delivery = $repository->loadClaimed($connection, $deliveryId, 'task08-ok'); $client = new Task08Client(new HttpResult(204, null, 12, 0)); (new WebhookHttpDispatcher($repository, $secrets, new Task08Validator(array('93.184.216.34')), $client))->dispatch($connection, 'task08-ok', $delivery ?: array()); $row = task08One($connection, 'SELECT WHK004_Status, WHK004_Last_Http_Status FROM WHK004 WHERE WHK004_Id = ?', 'i', array($deliveryId)); task08Assert($row['WHK004_Status'] === 'D' && (int) $row['WHK004_Last_Http_Status'] === 204, 'only 2xx marks delivery delivered'); task08Assert($client->body === $payload && HmacVerifier::verify($version->getPlaintextSecret(), (int) $client->headers['Hardness-Timestamp'], $payload, $client->headers['Hardness-Signature'], (int) $client->headers['Hardness-Timestamp']), 'HMAC signs the exact persisted raw bytes'); task08Assert(isset($client->headers['Hardness-Event-Id'], $client->headers['Hardness-Delivery-Id'], $client->headers['Hardness-Event-Type'], $client->headers['Hardness-Schema-Version']) && strpos(implode(' ', $client->headers), $version->getPlaintextSecret()) === false, 'contract headers omit secret');

    foreach (array(array(302, null, 'http_redirect', 'X'), array(429, null, 'http_retryable', 'R'), array(500, null, 'http_server_error', 'R'), array(null, 'curl_28', 'transport_error', 'R')) as $case) { $id = task08Delivery($connection, $companyId, $endpointId, $subscriptionId, $version->getId(), $url, '{}'); task08Assert($repository->tryClaim($connection, $id, 'task08-result'), 'result delivery claimed'); $claimed = $repository->loadClaimed($connection, $id, 'task08-result'); (new WebhookHttpDispatcher($repository, $secrets, new Task08Validator(array('93.184.216.34')), new Task08Client(new HttpResult($case[0], $case[1], 1, 4))))->dispatch($connection, 'task08-result', $claimed ?: array()); $history = task08One($connection, 'SELECT d.WHK004_Status, a.WHK005_Result FROM WHK004 d INNER JOIN WHK005 a ON a.WHK005_WHK004_Id = d.WHK004_Id WHERE d.WHK004_Id = ?', 'i', array($id)); task08Assert($history['WHK004_Status'] === $case[3] && $history['WHK005_Result'] === $case[2], 'Task 09 classification preserves safe HTTP history'); }

    $ssrfId = task08Delivery($connection, $companyId, $endpointId, $subscriptionId, $version->getId(), 'https://127.0.0.1/hook', '{}'); $repository->tryClaim($connection, $ssrfId, 'task08-ssrf'); $claimed = $repository->loadClaimed($connection, $ssrfId, 'task08-ssrf'); (new WebhookHttpDispatcher($repository, $secrets, new DestinationValidator(), new Task08Client(new HttpResult(200, null, 1, 0))))->dispatch($connection, 'task08-ssrf', $claimed ?: array()); $history = task08One($connection, 'SELECT d.WHK004_Status, a.WHK005_Result, a.WHK005_Transport_Error FROM WHK004 d INNER JOIN WHK005 a ON a.WHK005_WHK004_Id = d.WHK004_Id WHERE d.WHK004_Id = ?', 'i', array($ssrfId)); task08Assert($history['WHK004_Status'] === 'X' && $history['WHK005_Result'] === 'security_error' && $history['WHK005_Transport_Error'] === 'destination_rejected', 'SSRF destination never reaches HTTP client');

    $revokedId = task08Delivery($connection, $companyId, $endpointId, $subscriptionId, $version->getId(), $url, '{}'); $repository->tryClaim($connection, $revokedId, 'task08-revoked'); $secrets->revokeVersion($connection, $version->getId()); $claimed = $repository->loadClaimed($connection, $revokedId, 'task08-revoked'); (new WebhookHttpDispatcher($repository, $secrets, new Task08Validator(array('93.184.216.34')), new Task08Client(new HttpResult(200, null, 1, 0))))->dispatch($connection, 'task08-revoked', $claimed ?: array()); $history = task08One($connection, 'SELECT WHK004_Status FROM WHK004 WHERE WHK004_Id = ?', 'i', array($revokedId)); task08Assert($history['WHK004_Status'] === 'C', 'revoked secret cancels without a new HTTP attempt');

    $lostId = task08Delivery($connection, $companyId, $endpointId, $subscriptionId, $version->getId(), $url, '{}'); $repository->tryClaim($connection, $lostId, 'task08-old'); task08Exec($connection, 'UPDATE WHK004 SET WHK004_Lease_Until = DATE_SUB(UTC_TIMESTAMP(), INTERVAL 1 SECOND) WHERE WHK004_Id = ?', 'i', array($lostId))->close(); $repository->tryClaim($connection, $lostId, 'task08-new'); $old = $repository->loadClaimed($connection, $lostId, 'task08-old'); (new WebhookHttpDispatcher($repository, $secrets, new Task08Validator(array('93.184.216.34')), new Task08Client(new HttpResult(200, null, 1, 0))))->dispatch($connection, 'task08-old', $old ?: array()); $count = task08One($connection, 'SELECT COUNT(*) AS total FROM WHK005 WHERE WHK005_WHK004_Id = ?', 'i', array($lostId)); task08Assert((int) $count['total'] === 0, 'lost ownership cannot send or persist a result');
    echo "Task 08 synthetic tests passed.\n";
} finally { task08Cleanup($connection, $companyId); $connection->close(); }

